-- MySQL 8.4 canonical schema after PostgreSQL migrations 001-004.
-- IDs and tokens are generated by the application. All timestamps are UTC.

CREATE TABLE products (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,
  name VARCHAR(120) NOT NULL,
  unit_price_vnd INT NOT NULL,
  template_version VARCHAR(40) NOT NULL,
  is_active BOOLEAN NOT NULL DEFAULT TRUE,
  is_demo BOOLEAN NOT NULL DEFAULT TRUE,
  active_slot TINYINT GENERATED ALWAYS AS (CASE WHEN is_active THEN 1 ELSE NULL END) STORED,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  UNIQUE KEY one_active_product (active_slot),
  CONSTRAINT products_unit_price_nonnegative CHECK (unit_price_vnd >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE orders (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,
  order_number VARCHAR(24) NOT NULL UNIQUE,
  request_key CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL UNIQUE,
  product_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  product_snapshot JSON NOT NULL,
  recipient_snapshot JSON NOT NULL,
  quantity INT NOT NULL,
  unit_price_vnd INT NOT NULL,
  subtotal_vnd INT NOT NULL,
  currency CHAR(3) NOT NULL DEFAULT 'VND',
  customer_note VARCHAR(500) NOT NULL DEFAULT '',
  tracking_token_hash CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL UNIQUE,
  status VARCHAR(16) NOT NULL DEFAULT 'pending',
  version INT NOT NULL DEFAULT 1,
  tracking_code VARCHAR(80) NULL,
  cancellation_reason VARCHAR(500) NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  KEY orders_created_at_idx (created_at DESC, id),
  KEY orders_status_created_at_idx (status, created_at DESC),
  CONSTRAINT orders_product_fk FOREIGN KEY (product_id) REFERENCES products(id),
  CONSTRAINT orders_product_snapshot_object CHECK (JSON_TYPE(product_snapshot) = 'OBJECT'),
  CONSTRAINT orders_recipient_snapshot_object CHECK (JSON_TYPE(recipient_snapshot) = 'OBJECT'),
  CONSTRAINT orders_quantity_range CHECK (quantity BETWEEN 1 AND 100),
  CONSTRAINT orders_unit_price_nonnegative CHECK (unit_price_vnd >= 0),
  CONSTRAINT orders_subtotal_consistent CHECK (subtotal_vnd = unit_price_vnd * quantity),
  CONSTRAINT orders_currency_vnd CHECK (currency = 'VND'),
  CONSTRAINT orders_tracking_hash_format CHECK (REGEXP_LIKE(tracking_token_hash, '^[0-9a-f]{64}$', 'c')),
  CONSTRAINT orders_status_allowed CHECK (status IN ('pending','confirmed','producing','shipping','completed','cancelled')),
  CONSTRAINT orders_version_positive CHECK (version > 0),
  CONSTRAINT orders_cancellation_reason_required CHECK (status <> 'cancelled' OR (cancellation_reason IS NOT NULL AND CHAR_LENGTH(TRIM(cancellation_reason)) > 0))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE order_status_events (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,
  order_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  order_version INT NOT NULL,
  from_status VARCHAR(16) NULL,
  to_status VARCHAR(16) NOT NULL,
  actor VARCHAR(10) NOT NULL,
  internal_note VARCHAR(500) NULL,
  occurred_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  UNIQUE KEY order_status_events_order_version_unique (order_id, order_version),
  KEY order_status_events_order_idx (order_id, occurred_at, id),
  CONSTRAINT order_status_events_order_fk FOREIGN KEY (order_id) REFERENCES orders(id),
  CONSTRAINT order_status_events_version_positive CHECK (order_version > 0),
  CONSTRAINT order_status_events_from_allowed CHECK (from_status IS NULL OR from_status IN ('pending','confirmed','producing','shipping','completed','cancelled')),
  CONSTRAINT order_status_events_to_allowed CHECK (to_status IN ('pending','confirmed','producing','shipping','completed','cancelled')),
  CONSTRAINT order_status_events_actor_allowed CHECK (actor IN ('guest','admin','system'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE admin_sessions (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,
  token_hash CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL UNIQUE,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  expires_at DATETIME(3) NOT NULL,
  KEY admin_sessions_expiry_idx (expires_at),
  CONSTRAINT admin_sessions_hash_format CHECK (REGEXP_LIKE(token_hash, '^[0-9a-f]{64}$', 'c')),
  CONSTRAINT admin_sessions_expiry_after_creation CHECK (expires_at > created_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE order_items (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,
  order_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  position INT NOT NULL,
  design_snapshot JSON NOT NULL,
  quantity INT NOT NULL,
  photo_key VARCHAR(255) NOT NULL,
  preview_key VARCHAR(255) NOT NULL,
  UNIQUE KEY order_items_order_position_unique (order_id, position),
  CONSTRAINT order_items_order_fk FOREIGN KEY (order_id) REFERENCES orders(id),
  CONSTRAINT order_items_position_range CHECK (position BETWEEN 0 AND 9),
  CONSTRAINT order_items_design_snapshot_object CHECK (JSON_TYPE(design_snapshot) = 'OBJECT'),
  CONSTRAINT order_items_quantity_range CHECK (quantity BETWEEN 1 AND 10),
  CONSTRAINT order_items_photo_key_nonempty CHECK (photo_key <> ''),
  CONSTRAINT order_items_preview_key_nonempty CHECK (preview_key <> '')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
